#!/bin/sh
# Writes deploy/.env with random credentials for the local stack.
# deploy/.env is git-ignored. Re-run with --force to rotate.
#
# Use it from your shell too:  set -a; . deploy/.env; set +a
set -eu
dir=$(cd "$(dirname "$0")" && pwd)
out="$dir/.env"
if [ -e "$out" ] && [ "${1:-}" != "--force" ]; then
  echo "$out exists (use --force to overwrite)"; exit 0
fi
rand() { od -An -N24 -tx1 /dev/urandom | tr -d ' \n'; }
key="bd_test_$(rand)"
umask 077
cat > "$out" <<EOF
# Local-only credentials generated by deploy/dev-env.sh. Do not commit.
CLICKHOUSE_PASSWORD=$(rand)
BINDLE_API_KEY=$key
BINDLE_API_KEYS=$key=dev-tenant
BINDLE_ENDPOINT=http://localhost:4318
# Local-only: the query API on 127.0.0.1:8080 serves every request as this
# tenant until real console auth exists. Remove to make the API reject all.
BINDLE_API_DEV_AUTH_BYPASS_TENANT=dev-tenant
EOF
echo "wrote $out"
